// #859: the §6.5.x closed-list gate. The spec says every builtin gets a
// purity row in the SAME amendment that adds it, and that a missing row
// raises CXER0234 — but a `$`-only builtin (the `present` class) is outside
// `builtin_dispatchable`, so the runtime checker cannot see it. This test
// closes that hole at CI: it extracts every match-arm name from the
// evaluator's TWO dispatch surfaces (`invoke_builtin` — the `$`-call
// surface — and `builtin_dispatchable` — the bare-name surface) straight
// from the source, and requires a `builtin_purity_table()` row for each.
// A new builtin without its row is a RED test naming the offender, not a
// silently-pure escape. Source-scan by design: V cannot reflect over match
// arms, and a hand-maintained second list would just be a second honour
// system.
fn extract_match_arm_names_859(src string, fn_name string) []string {
	lines := src.split('\n')
	mut start := -1
	for i, l in lines {
		if l.starts_with('fn ${fn_name}(') {
			start = i
			break
		}
	}
	assert start >= 0, '#859 gate: fn ${fn_name} not found in eval.v — dispatch surface moved, update this gate'
	mut names := []string{}
	for i in start + 1 .. lines.len {
		l := lines[i]
		if l.starts_with('fn ') || l.starts_with('pub fn ') {
			break
		}
		// OUTER match arms sit at exactly two tabs; inner matches are deeper.
		if !l.starts_with('\t\t\'') {
			continue
		}
		mut rest := l
		for rest.contains('\'') {
			a := rest.index('\'') or { break }
			tail := rest[a + 1..]
			b := tail.index('\'') or { break }
			names << tail[..b]
			rest = tail[b + 1..]
		}
	}
	return names
}

fn test_every_dispatch_arm_has_a_purity_row_859() {
	eval_src := os.read_file(os.join_path(os.dir(@FILE), 'eval.v')) or {
		assert false, '#859 gate: cannot read eval.v beside this test: ${err}'
		return
	}
	table := builtin_purity_table()
	mut missing := []string{}
	for fn_name in ['invoke_builtin', 'builtin_dispatchable'] {
		arms := extract_match_arm_names_859(eval_src, fn_name)
		assert arms.len > 30, '#859 gate: only ${arms.len} arms extracted from ${fn_name} — the scan broke, fix the gate before trusting it'
		for a in arms {
			if a !in table {
				missing << '${a} (${fn_name})'
			}
		}
	}
	assert missing.len == 0, '#859: builtins dispatched but UNCLASSIFIED in builtin_purity_table — add the §6.5.x row in the amendment that adds the builtin: ${missing}'
}

fn test_unclassified_dispatchable_builtin_raises_0234_859() {
	// Runtime half: the checker raises CXER0234 for a dispatchable name
