		'text') or {
		assert false, 'classified-builtin pure def must be accepted: ${err}'
		return
	}
	assert ok.contains('2'), 'sanity: ${ok}'
}

fn test_wildcard_child_axis_lane_parity_847() {
	// #847: two $cx:equal values (same content address) must navigate
	// identically on EVERY axis. #587 fixed `//` for the bare-sequence
	// element body; `*` on the CHILD axis was the residue: the runtime
	// lane's __cx_seq__ marker element counted as ONE child while the
	// reparsed lane's bare SequenceNode matched nothing. `*` now matches
	// collection children through their marker views in BOTH walkers
	// (fast-path walk_path_step and the slow-path node-set collector).
	prog := '[?let
  [= \$t [c [?for [in \$x ("A","B")] [yield [x \$x]]]]]
  [= \$p [\$cx:parse [\$cx:canonical \$t]]]
  [list [\$count \$t/*] [\$count \$p/*] [\$count \$t//x] [\$count \$p//x]
        [= [\$cx:hash \$t] [\$cx:hash \$p]]]]'
	out := eval_code('', prog, 'text') or {
		assert false, '847 parity program failed: ${err}'
		return
	}
	// R-A1 (2026-08-25): [?for] in element content contributes one REAL
	// child per yield, so this program never builds an envelope — /* is 2
	// in BOTH lanes. The #847 invariant this test exists for (equal values
	// navigate identically, lane parity + hash equality) HOLDS at the new
	// values.
	assert out.contains('[list 2 2 2 2 true]'), '#847 lane parity broke: ${out}'
}

fn test_wildcard_child_axis_downstream_steps_847() {
	// The marker VIEW the wildcard emits must keep downstream steps
	// identical too: /*/x reaches the xs through the sequence node in
	// both lanes, /x stays 0 in both (the child axis does NOT dissolve
	// the sequence — that is what /* matching the marker preserves),
	// and the [?splice] idiom keeps its settled 2/2 on every axis.
	prog := '[?let
  [= \$t [c [?for [in \$x ("A","B")] [yield [x \$x]]]]]
  [= \$p [\$cx:parse [\$cx:canonical \$t]]]
  [= \$s [c [?splice [?for [in \$x ("A","B")] [yield [x \$x]]]]]]
  [= \$q [\$cx:parse [\$cx:canonical \$s]]]
  [list [\$count \$t/*/x] [\$count \$p/*/x] [\$count \$t/x] [\$count \$p/x]
        [\$count \$s/*] [\$count \$q/*]]]'
	out := eval_code('', prog, 'text') or {
		assert false, '847 downstream program failed: ${err}'
		return
	}
	// R-A1 (2026-08-25): the [?for] body contributes real [x …] children,
	// so /*/x is 0 (no x under an x) and /x is 2 (direct children) — in
	// BOTH lanes, pairwise parity intact; the [?splice] idiom keeps its
	// settled 2/2. The parsed-envelope opacity cells stay pinned by
	// program-pvmatrix-036/039.
	assert out.contains('[list 0 0 2 2 2 2]'), '#847 downstream/splice rows moved: ${out}'
}

