// ── source: vcx/code/http_pool_test.v ──
// http_pool_test.v — #234 client connection pool (§5.2 keep-alive reuse) over a
// live loopback server that COUNTS accepted connections. Proves: (1) two
// sequential requests to a keep-alive origin ride ONE connection; (2) a
// `Connection: close` response is never pooled; (3) a parked conn the server
// closed is dropped and redialed ONCE (no error, no request replay after
// bytes); (4) idle conns are evicted after http_pool_idle_ms.

@[heap]
struct PoolSrv {
mut:
	listener          &net.TcpListener
	port              int
	accepts           u64 // stdatomic
	conn_close_header bool // respond `Connection: close` + close after one exchange
	close_after_first bool // keep-alive response, then close the conn (stale-park)
}

fn pool_srv_start(conn_close_header bool, close_after_first bool) &PoolSrv {
	mut listener := net.listen_tcp(.ip, '127.0.0.1:0') or { panic('listen: ${err.msg()}') }
	addr := listener.addr() or { panic('addr: ${err.msg()}') }
	mut s := &PoolSrv{
		listener:          listener
		port:              addr.port() or { panic('port') }
		conn_close_header: conn_close_header
		close_after_first: close_after_first
	}
	spawn pool_srv_loop(mut s)
	return s
}

fn pool_srv_loop(mut s PoolSrv) {
	for {
		mut conn := s.listener.accept() or { return }
		stdatomic.add_u64(&s.accepts, 1)
		spawn pool_srv_conn(mut s, mut conn)
	}
}

fn pool_srv_conn(mut s PoolSrv, mut conn net.TcpConn) {
	for {
		mut req := []u8{}
		for {
			mut tmp := []u8{len: 4096}
			n := conn.read(mut tmp) or {
				conn.close() or {}
				return
			}
			if n <= 0 {
				conn.close() or {}
				return
			}
			req << tmp[..n]
			if req.bytestr().contains('\r\n\r\n') {
				break
			}
		}
		if s.conn_close_header {
			conn.write_string('HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: close\r\n\r\nhello') or {}
			conn.close() or {}
			return
		}
		conn.write_string('HTTP/1.1 200 OK\r\nContent-Length: 5\r\nConnection: keep-alive\r\n\r\nhello') or {}
		if s.close_after_first {
			// let the client finish reading + park the conn before the FIN lands
			time.sleep(100 * time.millisecond)
			conn.close() or {}
			return
		}
	}
}

struct PoolGetResult {
	status int
	ok     bool
}

fn pool_get(port int) PoolGetResult {
	r := http_do_single('GET', 'http://127.0.0.1:${port}/x', [][]string{}, []u8{}, HttpReqOpts{})
	st := http_response_status(r)
	return PoolGetResult{
		status: st
		ok:     st == 200
	}
}

fn test_pool_reuses_keepalive_connection() {
	caps_set_all()
	mut s := pool_srv_start(false, false)
	r1 := pool_get(s.port)
	assert r1.ok, 'first request must succeed (status ${r1.status})'
	r2 := pool_get(s.port)
	assert r2.ok, 'second request must succeed (status ${r2.status})'
	accepts := stdatomic.load_u64(&s.accepts)
	assert accepts == 1, 'two keep-alive requests must ride ONE connection (server accepted ${accepts})'
	s.listener.close() or {}
}

fn test_pool_never_pools_connection_close() {
	caps_set_all()
	mut s := pool_srv_start(true, false)
	r1 := pool_get(s.port)
	assert r1.ok
	r2 := pool_get(s.port)
	assert r2.ok
	accepts := stdatomic.load_u64(&s.accepts)
	assert accepts == 2, 'Connection: close responses must not be pooled (server accepted ${accepts})'
	s.listener.close() or {}
}

fn test_pool_stale_conn_redials_once() {
	caps_set_all()
	mut s := pool_srv_start(false, true)
	r1 := pool_get(s.port)
	assert r1.ok, 'first request must succeed'
	// server closes the parked conn after ~100ms; wait for the FIN to land
	time.sleep(300 * time.millisecond)
	r2 := pool_get(s.port)
	assert r2.ok, 'request over a stale parked conn must transparently redial (status ${r2.status})'
	accepts := stdatomic.load_u64(&s.accepts)
	assert accepts == 2, 'stale conn must be dropped and redialed once (server accepted ${accepts})'
	s.listener.close() or {}
}

fn test_pool_idle_eviction() {
	caps_set_all()
	mut s := pool_srv_start(false, false)
	r1 := pool_get(s.port)
	assert r1.ok
	key := http_pool_key('http', '127.0.0.1', s.port, true, '')
	// the conn is parked; take it, back-date it past the idle window, re-park it
	// directly (http_pool_put would reset the clock), then take again → evicted.
	mut pc := http_pool_take(key) or { panic('conn must be parked after a keep-alive exchange') }
	pc.last_ms = time.ticks() - http_pool_idle_ms - 1000
	g_http_pool_mu.lock()
	g_http_pool[key] = [pc]
	g_http_pool_total++
	g_http_pool_mu.unlock()
	if _ := http_pool_take(key) {
		panic('an idle-expired conn must be evicted, not handed out')
	}
	s.listener.close() or {}
}

// ── source: vcx/code/let_collapse_test.v ──
// let_collapse_test.v — unit coverage for the #361 cascading-let collapse
// (see let_collapse.v). Each case exercises one edge from the issue's
// checklist; the semantic backstop is the conformance suite run over the
// swept fixtures.

fn test_basic_two_level_collapse() {
	src := '[?let [= \$a 1]\n  [?let [= \$b 2]\n    [+ \$a \$b]]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == '[?let [= \$a 1]\n  [= \$b 2]\n  [+ \$a \$b]]\n'
}

fn test_three_level_chain_single_pass() {
	src := '[?let [= \$a 1]\n [?let [= \$b 2]\n  [?let [= \$c 3]\n   [+ \$a [+ \$b \$c]]]]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == '[?let [= \$a 1]\n [= \$b 2]\n [= \$c 3]\n [+ \$a [+ \$b \$c]]]\n'
}

fn test_comment_between_bindings_preserved() {
	src := '[?let [= \$a 1]\n  # picks the port\n  [?let [= \$b 2]\n    [+ \$a \$b]]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out.contains('# picks the port')
	assert out == '[?let [= \$a 1]\n  # picks the port\n  [= \$b 2]\n  [+ \$a \$b]]\n'
}

fn test_block_comment_inside_inner_preserved() {
	src := '[?let [= \$a 1]\n  [?let [= \$b 2] [; owner note ]\n    [+ \$a \$b]]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out.contains('[; owner note ]')
}

fn test_inner_let_not_sole_body_untouched() {
	// The inner let is a BINDING VALUE, not the body — no site.
	src := '[?let [= \$a [?let [= \$x 1] \$x]] [+ \$a 1]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == src
}

fn test_equality_shaped_body_not_swallowed() {
	// `[= $a $b]` in LAST position is the body (equality), not a binding;
	// there is no inner let, so nothing changes.
	src := '[?let [= \$a 1] [= \$b 1] [= \$a \$b]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == src
}

fn test_let_inside_string_untouched() {
	src := '[?let [= \$s "[?let [= \$x 1] \$x]"] \$s]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == src
}

fn test_bindingless_outer_wrapper_is_a_parse_error() {
	// `[?let [?let …]]` does not parse: parse_let_body requires the first
	// child to be a `[…]` clause opened by a plain `[` (a directive opener
	// `[?` is the retired-legacy error branch). Such a site cannot exist in
	// a valid file, and the tool must surface the parse failure rather than
	// rewrite unparseable text.
	if _ := collapse_nested_lets('[?let [?let [= \$a 1] \$a]]\n') {
		panic('expected parse error for bindingless [?let [?let …]] wrapper')
	}
}

fn test_multiline_string_indentation_untouched() {
	// The dedent pass must not strip spaces inside a multi-line string that
	// spans the pulled-up region.
	src := '[?let [= \$a 1]\n  [?let [= \$b "x\n    keep-these-spaces\n"]\n    [\$concat \$b [\$text \$a]]]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out.contains('\n    keep-these-spaces\n')
}

fn test_postfix_bang_body_untouched() {
	src := '[?let [= \$a 1] [\$f \$a]!]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == src
}

fn test_non_binding_preceding_child_skips_site() {
	// A malformed let (non-binding clause before the body) is left alone.
	src := '[?let [\$side-effect] [?let [= \$b 2] \$b]]\n'
	out := collapse_nested_lets(src) or { panic(err) }
	assert out == src
}

fn test_cxd_in_code_blocks_only() {
	src := '[test-suite name=t\n [case id=001\n  [in-code [#\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n#]]\n  [in-cx [#\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n#]]\n  [out-cx [#\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n#]]\n ]\n]\n'
	out := collapse_nested_lets_cxd(src) or { panic(err) }
	// in-code (the program) collapsed…
	assert out.contains('[in-code [#\n[?let [= \$a 1]\n [= \$b 2]\n [+ \$a \$b]]\n#]]')
	// …in-cx (the input DOCUMENT — test data) byte-identical…
	assert out.contains('[in-cx [#\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n#]]')
	// …expected-output block byte-identical.
	assert out.contains('[out-cx [#\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n#]]')
}

fn test_unparseable_input_errors_not_corrupts() {
	if _ := collapse_nested_lets('[?let [= $a') {
		panic('expected error on unparseable input')
	}
}

fn test_md_cx_fences_only() {
	src := '# Title\n\nProse with [?let untouched.\n\n```cx\n[?let [= \$a 1]\n [?let [= \$b 2]\n  [+ \$a \$b]]]\n```\n\n```json\n{"not": "[?let [?let]]"}\n```\n'
	out := collapse_nested_lets_md(src) or { panic(err) }
	assert out.contains('```cx\n[?let [= \$a 1]\n [= \$b 2]\n [+ \$a \$b]]\n```')
	assert out.contains('Prose with [?let untouched.')
	assert out.contains('{"not": "[?let [?let]]"}')
}

// ── source: vcx/code/lexer_test.v ──
// lexer_test.v — unit tests for the code lexer, focused on the
// triple-quote string literal support added for Bug C symmetry with
// the data parser's read_triple_quoted_str_with_quote.

// helper: tokenize and return only the string_lit tokens.
fn lex_strings(src string) ![]string {
	toks := cx.tokenize(src)!
	mut out := []string{}
	for t in toks {
		if t.kind == .string_lit {
			out << t.text
		}
	}
	return out
}

// helper: tokenize and return the first token kind.
fn lex_first(src string) !cx.ProgramTokenKind {
	toks := cx.tokenize(src)!
	if toks.len == 0 {
		return error('no tokens')
	}
	return toks[0].kind
}

// ── Triple-single-quote '''…''' ───────────────────────────────────────

fn test_triple_single_quote_basic() {
	strs := lex_strings("'''hello'''") or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1, 'expected 1 string token, got ${strs.len}'
	assert strs[0] == 'hello', 'expected content "hello", got "${strs[0]}"'
}

fn test_triple_single_quote_lookahead_on_close() {
	// '''hello'''' → content is "hello'" (lookahead-on-close)
	strs := lex_strings("'''hello''''") or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1, 'expected 1 string token'
	assert strs[0] == "hello'", 'expected "hello\'", got "${strs[0]}"'
}

fn test_triple_single_quote_multiline() {
	strs := lex_strings("'''line1\nline2'''") or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1
	assert strs[0] == 'line1\nline2', 'expected multiline content, got "${strs[0]}"'
}

fn test_triple_single_quote_contains_double_quote() {
	// Triple-single-quote can contain " without escaping.
	strs := lex_strings("'''say \"hello\"'''") or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1
	assert strs[0] == 'say "hello"', 'expected embedded double-quote, got "${strs[0]}"'
}

// ── Triple-double-quote """…""" ───────────────────────────────────────

fn test_triple_double_quote_basic() {
	strs := lex_strings('"""world"""') or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1, 'expected 1 string token, got ${strs.len}'
	assert strs[0] == 'world', 'expected content "world", got "${strs[0]}"'
}

fn test_triple_double_quote_lookahead_on_close() {
	// """world"""" → content is 'world"' (lookahead-on-close)
	strs := lex_strings('"""world""""') or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1, 'expected 1 string token'
	assert strs[0] == 'world"', 'expected "world\\"", got "${strs[0]}"'
}

fn test_triple_double_quote_verbatim_no_escape() {
	// Triple-quoted strings are verbatim — backslash is NOT an escape.
	// Content: it's a \"test\"  (literal backslashes stay)
	strs := lex_strings('"""it\'s a \\"test\\""""') or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1
	assert strs[0] == 'it\'s a \\"test\\"', 'expected verbatim backslash, got "${strs[0]}"'
}

fn test_triple_double_quote_multiline() {
	strs := lex_strings('"""line1\nline2"""') or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1
	assert strs[0] == 'line1\nline2', 'expected multiline content, got "${strs[0]}"'
}

// ── Single / double quotes still work unchanged ───────────────────────

fn test_single_quote_still_works() {
	strs := lex_strings("'hello'") or {
		assert false, 'lex error: ${err}'
		return
	}
	assert strs.len == 1
	assert strs[0] == 'hello'
}

fn test_double_quote_still_works() {
