// ── D-point spec-gap coverage ─────────────────────────────────────

fn test_d4_using_kind_shift_element_to_scalar_succeeds() {
	// (locked 2026-05-23): `:using` may return a value of any kind
	// regardless of focus kind; the returned value replaces the focus verbatim.
	// Element-focus + scalar-return is the canonical kind-shift case.
	//
	// This test pins the kind-shift contract:
	//   - eval must SUCCEED (no CXER0104)
	//   - result must contain the scalar return value in place of the elements
	//
	// CXER0104 is reserved for `:using` evaluators that fail to produce a value
	// (non-terminating, runtime trap inside the body) — NOT for legitimate
	// kind-shift. See spec/code.md §8.10.
	doc_src := '[doc [price 100] [price 200]]'
	code_src := '[?modify \$doc //price [using [?fn \$p "not-a-number"]]]'
	doc := cx.parse(doc_src) or {
		assert false, 'parse cx failed: ${err}'
		return
	}
	mut env := new_env()
	for i in 0 .. doc.elements.len {
		n := doc.elements[i]
		if n is cx.Element {
			env.bindings['doc'] = n
			break
		}
	}
	prog := cx.parse_program(code_src) or {
		assert false, 'parse code failed: ${err}'
		return
	}
	result := eval(prog.body, mut env) or {
		// Pre-lock impl path: any error including CXER0104 is now a spec
		// violation. Surface as a hard failure.
		assert false, 'kind-shift :using must succeed under D4 lock, got: ${err}'
		return
	}
	rendered := mt_render_text(result)
	// The string return value must appear in place of the <price> elements.
	assert rendered.contains('not-a-number'),
		'expected scalar return to replace element, got: ${rendered}'
}

fn test_d6_binding_path_focus() {
	// focus can reference a binding; CXPath on a binding uses
	// binding-path semantics. `$sec` is an element value;
	// `[?modify $sec //draft :delete]` strips draft children from that
	// sub-element, not from the document root. Identity invariant on $sec holds.
	doc_src := '[doc [section [draft yes] [final ok]] [section [draft yes] [other thing]]]'
	code_src := '[?for [in \$sec //section] [yield [?modify \$sec //draft [delete]]]]'
	result := eval_with_doc(doc_src, code_src) or {
		assert false, 'D6 binding-path focus failed: ${err}'
		return
	}
	rendered := mt_render_text(result)
	// Every section's draft child must be removed.
	assert !rendered.contains('draft'), 'draft children should be deleted, got: ${rendered}'
	// Non-draft children must survive.
	assert rendered.contains('final'), 'final child should survive, got: ${rendered}'
	assert rendered.contains('other'), 'other child should survive, got: ${rendered}'
}

fn test_d7_set_attr_on_attribute_step_raises_cxer0100() {
	// `:set-attr` / `:delete-attr` are always element-focused.
	// Parser (or pre-eval check) raises CXER0100 when the focus ends in an
	// attribute step.
	// Note: the current impl raises this at eval time (not parse time) in
	// apply_modify_action — see eval.v lines ~2530-2540. D7 spec says
	// "static error" but the implementation treats it as a pre-match runtime
	// check. The error code is correct (CXER0100); only the timing differs.
	doc_src := '[users [user name="Alice"]]'
	code_src := '[?modify \$doc //user/@name [set-attr status "active"]]'
	doc := cx.parse(doc_src) or {
		assert false, 'parse cx failed: ${err}'
		return
	}
	mut env := new_env()
	for i in 0 .. doc.elements.len {
		n := doc.elements[i]
		if n is cx.Element {
			env.bindings['doc'] = n
			break
		}
	}
	// The error may surface at parse time (static) or eval time (pre-match).
	// Test accepts either — what matters is CXER0100 is raised.
	prog := cx.parse_program(code_src) or {
		// Parse-time CXER0100 — spec-correct static error.
		assert err.msg().contains('CXER0100'),
			'expected CXER0100 at parse, got: ${err}'
		return
	}
	eval(prog.body, mut env) or {
		// Eval-time CXER0100 — impl raises it as a pre-match guard.
		assert err.msg().contains('CXER0100'),
			'expected CXER0100 at eval, got: ${err}'
		return
	}
	assert false, 'expected CXER0100 (static or eval-time) for :set-attr on attribute-step path'
}

// ── source: vcx/code/program_fmt_test.v ──
// program_fmt_test.v — #118 regression gate: code.fmt_source must NEVER rewrite
// a PROGRAM through the data emitter (the silent data-loss-on-save bug), must
// format DATA losslessly, and must be fail-closed (never emit a meaning-changing
// surface). This is the round-trip gate the data-only idempotence check missed.

const prog_118 = '[?lib \'cx-stdlib/store\' :as store]\n[?let\n  [= \$c [\$store:open "mem://"]]\n  [= \$h [\$store:put-doc \$c [note [body "hi"]]]]\n  \$h]'

fn test_program_not_data_corrupted() {
	out := fmt_source(prog_118) or { panic('fmt_source errored on a valid program: ${err}') }
	// the data-mangled `[('= …)]` sequence form must NEVER appear.
	assert !out.contains("[('"), 'program was data-corrupted:\n${out}'
	// the output must still parse as a program AND mean the same thing as the
	// input (compared via the position-free canonical program form).
	cf_in := program_node_to_source(cx.parse_program(prog_118) or { panic(err) }.body)
	cf_out := program_node_to_source(cx.parse_program(out) or {
		panic('fmt output no longer parses as a program: ${err}')
	}.body)
	assert cf_in == cf_out, 'fmt changed the program meaning:\nIN  ${cf_in}\nOUT ${cf_out}'
}

fn test_program_fmt_idempotent() {
	a := fmt_source(prog_118) or { panic(err) }
	b := fmt_source(a) or { panic(err) }
	assert a == b, 'fmt_source(fmt_source(program)) != fmt_source(program)'
}

fn test_data_formats_losslessly() {
	src := '[note [body "x"] [n 1]]'
	out := fmt_source(src) or { panic('fmt_source errored on data: ${err}') }
	assert out.contains('[note'), out
	assert !out.contains("[('"), out
	// lossless as data: re-parses to the same data tree.
	d1 := cx.parse(src) or { panic(err) }
	d2 := cx.parse(out) or { panic('formatted data no longer parses: ${err}') }
	assert cx.emit_cx(d1) == cx.emit_cx(d2), 'data fmt was not lossless'
}

fn test_config_data_formats() {
	src := '[cxstore-service [bind addr="127.0.0.1:7800"] [stores [store name="t" url="mem://x"]]]'
	out := fmt_source(src) or { panic('fmt_source errored on config: ${err}') }
	assert out.contains('[cxstore-service'), out
	assert !out.contains("[('"), out
}

fn test_data_with_url_and_slashes_formats() {
	// data containing `//` (URLs) and `:` atoms must still format, not error
	// (these are NOT program surface — the earlier naive token-scan broke here).
	src := '[store [url "http://h//p"] [alt "mem://x"]]'
	out := fmt_source(src) or { panic('fmt_source errored on url data: ${err}') }
	assert out.contains('[store'), out
}

// ── #967 — `cx fmt` is the LOSSLESS canonical formatter ────────────────────
//
// cli.md:107/:209 define `cx fmt` as lossless canonical: comments and anchors
// are preserved, whitespace and quoting normalised. canonical.md §1.2 makes
// comments EXACTLY what separates lossless canonical from strict canonical.
// Measured before the fix: every comment in every position was deleted.
//
// Root cause (measured, not assumed): fmt_source discriminates data from
// program by asking whether the DATA formatting preserves the source's
// PROGRAM reading. The data emitter's canonical quoting drops quotes the bare
// image re-reads identically — in the DATA reading. In the PROGRAM reading a
// bare body word is a CALL (`[name "demo"]` holds a string_lit, `[name demo]`
// holds a ProgramCall), so a plain data document carrying a quoted string is
// classified as "a real program" and routed to the program lane — whose
// parser (cx.tokenize / parse_program) discards comments outright, so the
// canonical text comes back with every comment gone.
//
// The fix keeps the meaning guard (it is right: string → call IS a meaning
// change) and stops that lane from ever seeing a comment-bearing source.

fn count_comments_in_data_reading(src string) int {
	doc := cx.parse(src) or { return -1 }
	mut n := 0
	for c in doc.prolog {
		n += count_comments_in_node(c)
	}
	for e in doc.elements {
		n += count_comments_in_node(e)
	}
	return n
}

fn count_comments_in_node(n cx.Node) int {
	if n is cx.CommentNode {
		return 1
	}
	if n is cx.Element {
		mut t := 0
		for it in n.items {
			t += count_comments_in_node(it)
		}
		return t
	}
	return 0
}

// The four positions of #967's table: line / block × top-level / element-body.
// The quoted `"demo"` body is the issue's own spelling — and the shape that
// triggers the misclassification, so it is load-bearing, not incidental.
const fmt_967_positions = [
	'[xap\n# c\n[name "demo"]\n]\n',
	'[xap [; c ] [name "demo"]]\n',
	'# c\n[xap [name "demo"]]\n',
	'[; c ]\n[xap [name "demo"]]\n',
	// the same four with an unquoted body — these route through the data
	// lane's lossless emitter and come back NORMALISED, comments intact.
	'[xap\n# c\n[name demo]\n]\n',
	'[xap [; c ] [name demo]]\n',
	'# c\n[xap [name demo]]\n',
	'[; c ]\n[xap [name demo]]\n',
]

fn test_967_fmt_preserves_comments_in_every_position() {
	for src in fmt_967_positions {
		want := count_comments_in_data_reading(src)
		assert want == 1, 'fixture is wrong, not the formatter: ${src}'
		out := fmt_source(src) or {
			assert false, 'fmt_source errored on ${src}: ${err}'
			continue
		}
		assert out.contains('c'), 'comment text gone from `${src}` -> `${out}`'
		got := count_comments_in_data_reading(out)
		assert got == want, 'cx fmt DELETED a comment: `${src}` -> `${out}` (${want} -> ${got})'
	}
}

fn test_967_fmt_output_reparses_in_every_position() {
	for src in fmt_967_positions {
		out := fmt_source(src) or {
			assert false, 'fmt_source errored on ${src}: ${err}'
			continue
		}
		cx.parse(out) or {
			assert false, 'cx fmt output does not re-parse: `${src}` -> `${out}`: ${err}'
			continue
		}
	}
}

fn test_967_fmt_is_idempotent_on_comment_bearing_sources() {
	// formatting.md §7 — and the shape the bug fix could most easily break:
	// a lane that returns its input verbatim grows a trailing newline per run
	// unless the trailing newline is normalised.
	for src in fmt_967_positions {
		a := fmt_source(src) or {
			assert false, 'fmt_source errored on ${src}: ${err}'
			continue
		}
		b := fmt_source(a) or {
			assert false, 'fmt_source(fmt_source(x)) errored on ${src}: ${err}'
			continue
		}
		assert a == b, 'fmt is not idempotent on `${src}`: `${a}` != `${b}`'
	}
}

fn test_967_fmt_purity_the_data_tree_is_unchanged() {
	// formatting.md §1 purity: same tree in, same tree out — presentation
	// only. This is what makes "preserved the comment" mean the comment is
	// still in the same PLACE, not merely present somewhere in the text.
	for src in fmt_967_positions {
		out := fmt_source(src) or {
			assert false, 'fmt_source errored on ${src}: ${err}'
			continue
		}
		d_in := cx.parse(src) or {
			assert false, 'fixture does not parse: ${src}'
			continue
		}
		d_out := cx.parse(out) or {
			assert false, 'fmt output does not parse: ${out}'
			continue
		}
		assert cx.emit_cx(d_in) == cx.emit_cx(d_out), 'cx fmt changed the tree: `${src}` -> `${out}`'
	}
}

fn test_967_comment_bearing_program_keeps_its_comments() {
	// A genuine PROGRAM carrying comments. The program lane cannot emit them
	// (its parser drops them), so fmt must fail closed on the source rather
	// than ship a comment-stripped canonicalization — silent data loss in the
	// command the LSP calls on save.
	src := '[?lib \'cx-stdlib/store\' :as store]\n# open the store first\n[?let\n  [= \$c [\$store:open "mem://"]]\n  \$c]'
	out := fmt_source(src) or { panic('fmt_source errored on a valid program: ${err}') }
	assert out.contains('# open the store first'), 'cx fmt deleted a comment from a PROGRAM file:\n${out}'
	assert !out.contains("[('"), 'program was data-corrupted:\n${out}'
	twice := fmt_source(out) or { panic('fmt(fmt) errored: ${err}') }
	assert twice == out, 'fmt is not idempotent on a comment-bearing program'
}

fn test_967_comment_free_sources_are_untouched_by_the_fix() {
	// The comment-free program lane must be byte-identical to its pre-fix
	// behaviour — the fix is scoped to comment-bearing sources precisely so
	// no golden moves for anything else.
	for src in ['[xap [name "demo"]]', prog_118, '[note [body "x"] [n 1]]'] {
		a := fmt_source(src) or {
			assert false, 'fmt_source errored on ${src}: ${err}'
			continue
		}
		b := fmt_source(a) or {
			assert false, 'fmt(fmt) errored on ${src}: ${err}'
			continue
		}
		assert a == b, 'fmt not idempotent on comment-free `${src}`'
		assert !a.ends_with('\n'), 'fmt lanes return unterminated text: `${a}`'
	}
}

// ── source: vcx/code/render_test.v ──
// render_test.v — unit tests for render_element_to / render_attr_value_to.
// Gate: attribute values that contain `"` must survive round-trip without
// breaking the surrounding quotes (Bug A fix: route through choose_render_quote).

fn test_attr_value_with_embedded_double_quote_uses_single_quote() {
	// Value contains a `"` character — the renderer must pick single-quote
	// wrapping, not the broken `"value with "quotes""` form.
	el := cx.Element{
		name:  'row'
		attrs: [cx.Attribute{ name: 'notes', value: cx.ScalarValue('value with "embedded" quotes') }]
		items: []
	}
	got := render_element(el)
	// The rendered form must NOT contain `"value with` (which would mean a
	// raw double-quote wrap starting at the embedded double-quote boundary).
	// It must contain the single-quoted form instead.
	assert got.contains("'value with \"embedded\" quotes'"),
		'expected single-quoted attr value, got: ${got}'
	assert !got.starts_with('[row notes="value with'),
		'double-quote wrap would break re-parse, got: ${got}'
}

fn test_attr_value_plain_string_round_trips() {
	// Plain value (no special chars) still renders as bare unquoted form.
	el := cx.Element{
		name:  'item'
		attrs: [cx.Attribute{ name: 'id', value: cx.ScalarValue('abc') }]
		items: []
	}
	got := render_element(el)
	assert got == '[item id=abc]', 'expected bare unquoted attr, got: ${got}'
}

fn test_attr_value_with_spaces_uses_single_quote() {
	// Value with spaces but no `'` — single-quoted (the default quoting
	// form per spec/core/canonical.md §2.3; single is preferred over double).
	el := cx.Element{
		name:  'p'
		attrs: [cx.Attribute{ name: 'class', value: cx.ScalarValue('foo bar') }]
		items: []
	}
	got := render_element(el)
	assert got == "[p class='foo bar']", 'expected single-quoted attr, got: ${got}'
}

fn test_attr_value_with_both_quote_styles_uses_single_escaped() {
	// Value with both `"` and `'` — single-quoted with `\'` escape (the
	// §2.3 line 130 tiebreak; the `"` needs no escape inside `'…'`).
	// Triple-quoting is multiline-only, NOT an escape-avoidance device.
	el := cx.Element{
		name:  'x'
		attrs: [cx.Attribute{ name: 'v', value: cx.ScalarValue("it's a \"test\"") }]
		items: []
	}
	got := render_element(el)
	assert got == '[x v=\'it\\\'s a "test"\']', 'expected single-escaped attr, got: ${got}'
}

// #620: a TextNode in ITEM position (map row value / sequence / array entry)
// renders with the same round-trip quoting rule as element bodies — bare text
// that would auto-type or split must quote, bare-safe names stay bare. The
// observed defect: journal-replayed records (whose fields are data-parsed
// TextNodes) rendered `n: 5` where the live lane rendered `n: '5'` — a silent
// type flip on re-import, violating the #587/#618 lane-parity invariant.
fn test_map_row_text_item_quotes_for_round_trip() {
	rec := cx.Element{
		name:  '__cx_map__'
		items: [
			cx.Node(cx.Element{ name: 'actor', items: [cx.Node(cx.TextNode{ value: 'u' })] }),
			cx.Node(cx.Element{ name: 'n', items: [cx.Node(cx.TextNode{ value: '5' })] }),
			cx.Node(cx.Element{ name: 's', items: [
				cx.Node(cx.ScalarNode{ value: cx.ScalarValue('5'), data_type: cx.ScalarType.string_type }),
			] }),
		]
	}
	got := render_canonical(rec)
	// bare-safe text stays bare; auto-typing text quotes; and the TextNode
	// renders IDENTICALLY to the equal string scalar (lane parity).
	assert got == "{actor: u, n: '5', s: '5'}", 'map-row text quoting wrong: ${got}'
}

fn test_sequence_text_item_quotes_for_round_trip() {
	seq := cx.Element{
		name:  '__cx_seq__'
		items: [
			cx.Node(cx.TextNode{ value: 'plain' }),
			cx.Node(cx.TextNode{ value: '42' }),
			cx.Node(cx.TextNode{ value: 'two words' }),
		]
	}
	got := render_canonical(seq)
	assert got == "(plain, '42', 'two words')", 'sequence text quoting wrong: ${got}'
}

// ── source: vcx/code/slice_postfix_test.v ──
// slice_postfix_test.v — parser tests for 
//
// Covers the BindingPostfix → SliceAxes grammar
// "Surface-syntax summary") and the positional disambiguation table.
// These tests confirm the AST shape only; evaluation is deferred to
// W5c (the evaluator stub returns CXER0100 "slice eval: deferred to
// W5c", which has its own coverage at the conformance layer in
// conformance/code.txt under `program-slice-w*`).
//
// Surface forms covered:
//   1. $xs[2:5]           — closed range with explicit start/stop
//   2. $xs[:5]            — open start
//   3. $xs[-3:]           — open stop with negative start
//   4. $xs[::2]           — strided (start/stop open, step=2)
//   5. $xs[::-1]          — reversed walk (step=-1)
//   6. $xs[*]             — full axis
//   7. $xs[2]             — single-Expr postfix; per the brief, the
//                          axis is recorded as kind=.single (the
//                          parser-level decision: a single integer
//                          without `:` / `*` / `,` still routes
//                          through the BindingPostfix path)
//   8. $xs[2:$_last]      — range with $_last on the RHS
//   9. $xs[2:5, 3:8]      — multi-axis (two range axes)
//
// regression: a bare `[1, 2, 3]` at expression head is
// still an array literal — the slice surface is gated by a preceding
// `$binding`, not the bracket shape alone.

// extract_slice unwraps a `cx.Program{body}` and asserts the body is a
// cx.ProgramSliceAccess. Used by every test below.
fn extract_slice(src string) ?cx.ProgramSliceAccess {
	prog := cx.parse_program(src) or {
		eprintln('parse failed for ${src}: ${err.msg()}')
		return none
	}
	body := prog.body
	if body is cx.ProgramSliceAccess {
		return body
	}
	eprintln('expected cx.ProgramSliceAccess, got ${body.type_name()} for ${src}')
	return none
}

// expect_int extracts an int literal from a cx.ProgramNode payload.
fn expect_int(n cx.ProgramNode, want i64) bool {
	if n is cx.ProgramLiteral && n.kind == .int_lit {
		return n.int_val == want
	}
	return false
}

// expect_binding_name extracts a bare-binding name from a cx.ProgramNode.
fn expect_binding_name(n cx.ProgramNode, want string) bool {
	if n is cx.ProgramBinding {
		return n.name == want && n.path.len == 0
	}
	return false
}

// ── 1. $xs[2:5] — closed range with explicit start/stop ──────────────────────

fn test_slice_closed_range() {
	s := extract_slice('\$xs[2:5]') or { assert false, 'extract failed' return }
	assert s.binding.name == 'xs'
	assert s.binding.path.len == 0
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	start := ax.start or { assert false, 'expected start expression' return }
	stop  := ax.stop  or { assert false, 'expected stop expression'  return }
	assert ax.step == none
	assert expect_int(start, 2), 'start should be 2'
	assert expect_int(stop,  5), 'stop should be 5'
}

// ── 2. $xs[:5] — open start ──────────────────────────────────────────────────

fn test_slice_open_start() {
	s := extract_slice('\$xs[:5]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	assert ax.start == none, 'start should be absent'
	stop := ax.stop or { assert false, 'expected stop expression' return }
	assert ax.step == none
	assert expect_int(stop, 5)
}

// ── 3. $xs[-3:] — open stop with negative start ──────────────────────────────

fn test_slice_negative_start_open_stop() {
	s := extract_slice('\$xs[-3:]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	start := ax.start or { assert false, 'expected start expression' return }
	assert ax.stop == none, 'stop should be absent'
	assert ax.step == none
	assert expect_int(start, -3), 'start should be -3'
}

// ── 4. $xs[::2] — strided, both bounds open ──────────────────────────────────

fn test_slice_strided() {
	s := extract_slice('\$xs[::2]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	assert ax.start == none
	assert ax.stop  == none
	step := ax.step or { assert false, 'expected step expression' return }
	assert expect_int(step, 2)
}

// ── 5. $xs[::-1] — reversed walk ─────────────────────────────────────────────

fn test_slice_reversed() {
	s := extract_slice('\$xs[::-1]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	assert ax.start == none
	assert ax.stop  == none
	step := ax.step or { assert false, 'expected step expression' return }
	assert expect_int(step, -1)
}

// ── 6. $xs[*] — full axis ────────────────────────────────────────────────────

fn test_slice_full_axis() {
	s := extract_slice('\$xs[*]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .full
	assert ax.start == none
	assert ax.stop  == none
	assert ax.step  == none
}

// ── 7. $xs[2] — single-index axis (W5c tightening) ───────────────────────────
//
// W5b parsed `$xs[2]` as the predicate-fallback case (two adjacent
// expressions: a `$xs` binding and a `[2]` array literal). W5c promotes
// the form to a structured `cx.ProgramSliceAccess` with a single `.single`
// axis carrying the integer expression — closing the disambiguation
// gap noted in the W5b brief and unblocking conformance fixture
// `program-slice-007-single-index` (`$xs[3]` → c).

fn test_slice_single_index_axis() {
	s := extract_slice('\$xs[3]') or { assert false, 'extract failed' return }
	assert s.binding.name == 'xs'
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .single
	start := ax.start or { assert false, 'expected start expression' return }
	assert ax.stop == none
	assert ax.step == none
	assert expect_int(start, 3), 'single-index axis should carry 3'
}

// ── 8. $xs[2:$_last] — range with $_last on RHS ──────────────────────────────

fn test_slice_with_last_binding() {
	s := extract_slice('\$xs[2:\$_last]') or { assert false, 'extract failed' return }
	assert s.axes.len == 1
	ax := s.axes[0]
	assert ax.kind == .range
	start := ax.start or { assert false, 'expected start' return }
	stop  := ax.stop  or { assert false, 'expected stop'  return }
	assert ax.step == none
	assert expect_int(start, 2)
	assert expect_binding_name(stop, '_last')
}

// ── 9. $xs[2:5, 3:8] — multi-axis (parsed, not evaluated) ────────────────────

fn test_slice_multi_axis_two_ranges() {
	s := extract_slice('\$xs[2:5, 3:8]') or { assert false, 'extract failed' return }
	assert s.axes.len == 2

	ax0 := s.axes[0]
	assert ax0.kind == .range
	assert expect_int(ax0.start or { assert false return }, 2)
	assert expect_int(ax0.stop  or { assert false return }, 5)

	ax1 := s.axes[1]
	assert ax1.kind == .range
	assert expect_int(ax1.start or { assert false return }, 3)
	assert expect_int(ax1.stop  or { assert false return }, 8)
}

// ── regression: bare [1, 2, 3] is an array literal ───────────────
//
// The slice surface is GATED by a preceding `$binding`. A bracket
// expression at expression head (no leading binding) remains an array
// literal — this test pins that the W5b parser change
// doesn't accidentally re-route bracket-head expressions.

fn test_array_literal_unchanged_at_expression_head() {
	prog := cx.parse_program('[1, 2, 3]') or {
		assert false, 'parse [1, 2, 3] failed: $err'
		return
	}
	body := prog.body
	if body is cx.ProgramLiteral {
		assert body.kind == .array_lit, 'expected array_lit, got ${body.kind}'
		assert body.items.len == 3
	} else {
		assert false, 'expected cx.ProgramLiteral for [1, 2, 3], got ${body.type_name()}'
	}
}

// ── disambiguation: $xs[2] differs from /step[2] ────────────────────
//
// `$xs[2]` parses as a slice-single axis (this milestone).
// `[?for $x :in //user[2] :yield $x]` — the `//user[2]` is a CXPath
// step with a positional predicate (predicate kind=.position).
// We confirm the existing predicate parsing path is untouched.

fn test_cxpath_predicate_still_position() {
	// Parse a CXPath head; the predicate on a NodeTest must remain
	// a positional predicate, NOT a slice.
	prog := cx.parse_program('//user[2]') or {
		assert false, 'parse //user[2] failed: $err'
		return
	}
	body := prog.body
	if body is cx.ProgramPathExpr {
		assert body.steps.len == 1
		assert body.steps[0].predicates.len == 1
		pred := body.steps[0].predicates[0]
		assert pred.kind == .position, 'expected .position, got ${pred.kind}'
		assert pred.int_index == 2
	} else {
		assert false, 'expected cx.ProgramPathExpr for //user[2], got ${body.type_name()}'
	}
}

// ── source: vcx/code/stdlib_caps_test.v ──
// stdlib_caps_test.v — capability-spec parsing: the net host-scope support
// (#105 §6.1 — a scoped grant registers the host so the grant is
// least-privilege AND a literal-IP scope overrides the §4.5 private-range
// deny, net.md §4.5; #47), plus the #713 fail-closed rules:
//   - `cap=resource` is THE scope spelling (L114: the `cap:` spelling is
//     reserved for capability-value addresses, governance §12.3 — a grant
//     token containing `:` is refused, one spelling one meaning);
//   - an unknown capability name is a LOUD typed error (CXER0274), never a
//     silent no-grant (a typo'd grant that silently denies makes denial
//     fixtures false-green and grant surfaces lie).
// On any refused spec the active set is NOT modified.

fn test_caps_net_scope_registers_host() {
	caps_apply_spec('net=127.0.0.1:64999') or { assert false, err.msg() }
	assert cap_allowed('net'), 'net must be granted'
	assert cap_net_specs() == ['127.0.0.1:64999'], 'host scope must be recorded: ${cap_net_specs()}'
	assert !cap_net_is_all(), 'a scoped net grant is not unscoped'
	caps_set_empty()
}

fn test_caps_bare_net_is_unscoped() {
	caps_apply_spec('net') or { assert false, err.msg() }
	assert cap_net_is_all(), 'bare net is unscoped (all hosts, deny-set still applies)'
	assert cap_net_specs().len == 0
	caps_set_empty()
}

fn test_caps_mixed_list_with_net_scope() {
	caps_apply_spec('read,write,net=example.com:443') or { assert false, err.msg() }
	assert cap_allowed('read') && cap_allowed('write') && cap_allowed('net')
	assert cap_net_specs() == ['example.com:443']
	assert !cap_net_is_all()
	caps_set_empty()
}

// #1059, ABI surface: read/write/env scoping is NOT IMPLEMENTED, so a
// `cap=resource` suffix on those three REFUSES (typed CXER0274, no set
// installed) instead of silently installing BLANKET authority. The CLI's
// five parse sites refuse at exit 2; this pins the sixth grant surface
// (`cx_code_eval_caps` and every embedder riding caps_apply_spec) to the
// same discipline. Real scoping is #1061.
fn test_caps_unenforced_scope_suffix_refuses_abi() {
	caps_set_empty()
	for spec in ['read=/nonexistent', 'write=/tmp', 'env=HOME', 'read=,write'] {
		caps_apply_spec(spec) or {
			assert err.msg().contains('NOT IMPLEMENTED'), 'refusal must say scoping is unimplemented: ${err.msg()}'
			assert err.msg().contains('1061'), 'refusal must name the scoping-design issue: ${err.msg()}'
			assert err.msg().contains('CXER0274'), 'refusal must carry the typed code: ${err.msg()}'
			continue
		}
		assert false, 'spec `${spec}` must refuse (unenforced scope suffix)'
	}
	// On a refused spec the active set is NOT modified — nothing from the
	// tokens before the offending one leaks in.
	caps_apply_spec('read,write=/x') or {
		assert !cap_allowed('read'), 'a refused spec must install NOTHING'
		caps_set_empty()
		return
	}
	assert false, 'read,write=/x must refuse'
}

fn test_caps_empty_is_pure_only() {
	caps_apply_spec('') or { assert false, err.msg() }
	assert !cap_allowed('net') && !cap_allowed('read') && !cap_allowed('write'), 'empty spec grants nothing'
	caps_set_empty()
}

fn test_caps_all_bypasses_scope() {
	caps_apply_spec('all') or { assert false, err.msg() }
	assert cap_private_range_allowed(), 'all/* is the full opt-out (private-range deny bypassed)'
