}

// ── L104 (#713 item 3): allow_all NORMALIZES to explicit-full +
//    a private-range-policy field — one canonical form, not two ────────────────

fn test_caps_all_normalizes_to_explicit_full() {
	caps_apply_spec('all') or { assert false, err.msg() }
	for cap in capability_names() {
		assert cap_allowed(cap), '`all` must grant ${cap} EXPLICITLY (normalized form)'
	}
	assert cap_private_range_allowed(), 'the opt-out carries the private-range-policy field'
	// The explicit nine-grant set is the SAME grant set minus the policy field.
	caps_apply_spec(capability_names().join(',')) or { assert false, err.msg() }
	for cap in capability_names() {
		assert cap_allowed(cap), 'explicit list grants ${cap}'
	}
	assert !cap_private_range_allowed(), 'an explicit list never bypasses the private-range deny set'
	caps_set_empty()
}

