fn test_dm_diacritics_fold() {
	p1, a1 := similar_double_metaphone('José')
	assert p1 == 'HS'
	assert a1 == 'HS'
	p2, a2 := similar_double_metaphone('Muñoz')
	assert p2 == 'MNS'
	assert a2 == 'MNS'
	// folded input must key identically to its plain-ASCII spelling
	p3, a3 := similar_double_metaphone('café')
	p4, a4 := similar_double_metaphone('cafe')
	assert p3 == p4
	assert a3 == a4
	p5, _ := similar_double_metaphone('François')
	assert p5 == 'FRNS'
}

fn test_dm_empty_and_nonletter() {
	p1, a1 := similar_double_metaphone('')
	assert p1 == ''
	assert a1 == ''
	p2, a2 := similar_double_metaphone('123')
	assert p2 == ''
	assert a2 == ''
}

fn test_metaphone_score_exact_and_primary() {
	// case-insensitive equality wins outright
	assert similar_metaphone_score('Smith', 'smith') == 1.0
	// primary/primary key match
	assert similar_metaphone_score('SMITH', 'SMYTHE') == 1.0
	assert similar_metaphone_score('Katherine', 'Catherine') == 1.0
	assert similar_metaphone_score('nation', 'nashun') == 1.0
}

fn test_metaphone_score_alternate() {
	// SMITH (SM0/XMT) vs SCHMIDT (XMT/SMT): primary meets alternate
	assert similar_metaphone_score('SMITH', 'SCHMIDT') == 0.8
	// YANKELOVICH (ANKL/ANKL) vs JANKELOWICZ (JNKL/ANKL)
	assert similar_metaphone_score('YANKELOVICH', 'JANKELOWICZ') == 0.8
}

fn test_metaphone_score_mismatch_and_edges() {
	assert similar_metaphone_score('SMITH', 'JONES') == 0.0
	// empty inputs: equal strings still score 1.0
	assert similar_metaphone_score('', '') == 1.0
	assert similar_metaphone_score('abc', '') == 0.0
	// keyless inputs (digits) only match by literal equality
	assert similar_metaphone_score('123', '123') == 1.0
	assert similar_metaphone_score('123', '456') == 0.0
	// diacritics fold before keying
	assert similar_metaphone_score('José', 'Jose') == 1.0
}

fn test_metaphone_score_multiword() {
	// per-word keys joined with ' ' — both sides key to 'JN SM0'
	assert similar_metaphone_score('JOHN SMITH', 'JON SMYTH') == 1.0
	assert similar_metaphone_score('JOHN SMITH', 'JANE DOE') == 0.0
}

// ── source: vcx/code/worker_cancel_test.v ──
// worker_cancel_test.v — determinism tests for [?cancel] on a concurrent
// [?worker] (spec/code.md §10.4.2/§10.4.3 blocking channel ops, §10.5.4
// cooperative cancellation, §10.5.7.2 cancellation-point precedence).
//
// The program-conc-016/017/020 conformance fixtures cancel a worker whose
// body is expected to be BLOCKED at a cancellation point. On the concurrent
// worker substrate the pre-fix [?send]/[?receive] never blocked (the
// single-threaded-substrate simplification), so the worker body raced the
// main thread's [?cancel]: under CPU starvation the body ran to completion
// first and [?wait-for] surfaced the body's value ([ok]) instead of the
// WORKER_CANCELLED chain — the flake observed on the 2026-07-04 cold gate.
// These tests pin the spec semantics under ADVERSARIAL scheduling: the main
// thread sleeps long enough that a non-blocking body would always win the
// race before [?cancel] is issued.

const cancel_chain_outer = 'cx-err:CXER0221'

const cancel_chain_cause = 'cx-err:CXER0260'

fn eval_step(mut env MatchEnv, src string) cx.Node {
	prog := cx.parse_program(src) or { panic('parse failed: ${err.msg()}\n${src}') }
	return eval(prog.body, mut env) or { panic('eval failed: ${err.msg()}\n${src}') }
}

// worker_rec fetches the WorkerRecord for `name` (test-side observability).
fn worker_rec(mut env MatchEnv, name string) &WorkerRecord {
	mut st := env.state
	return st.worker_get(name) or { panic('no worker record "${name}"') }
}

// join_done spin-waits (up to `ms` milliseconds) for the worker body's
// thread to publish its terminal state.
fn join_done(rec &WorkerRecord, ms int) bool {
	mut waited := 0
	for !rec.done {
		if waited >= ms {
			return false
		}
		time.sleep(time.millisecond)
		waited++
	}
	return true
}

// §10.4.2: a worker's [?send] on an unbuffered channel with no receiver
// MUST block (it is also a §10.5.4 cancellation point). Cancelling the
// blocked worker MUST surface the WORKER_CANCELLED/CANCELLED chain from
// [?wait-for] — regardless of how late the [?cancel] arrives.
// (program-conc-017-send-cancelled, de-raced.)
fn test_send_cancel_deterministic_under_adversarial_delay() {
	caps_set_all()
	mut env := new_env()
	eval_step(mut env, '[?let [= $ch [?channel name="tc17" buffer=0]] [?worker name="tw17" [body [?send "blocked" to=$ch]]]]')
	// Adversarial scheduling: with a non-blocking send the body completes
	// within microseconds; 200ms guarantees the pre-fix race is ALWAYS lost.
	time.sleep(200 * time.millisecond)
	rec := worker_rec(mut env, 'tw17')
	assert !rec.done, '[?send] on an unbuffered channel with no receiver must block (§10.4.2); worker completed with: ${render_canonical(rec.result)}'
	res := eval_step(mut env, '[?let [= $h [?worker-handle name="tw17"]] [?let [= $_ [?cancel worker=$h]] [?wait-for worker=$h]]]')
	rendered := render_canonical(res)
	assert rendered.contains(cancel_chain_outer), 'expected WORKER_CANCELLED chain, got: ${rendered}'
	assert rendered.contains(cancel_chain_cause), 'expected CANCELLED cause, got: ${rendered}'
	// The blocked body must EXIT via the cancellation point (§10.5.4) —
	// a leaked forever-blocked thread means send never observed the cancel.
	assert join_done(rec, 2000), 'worker body never exited its blocked [?send] after [?cancel]'
	assert rec.cancelled
}

// §10.4.3: a worker's [?receive] on an empty open channel MUST block (and
// is a cancellation point). (program-conc-016-receive-cancelled, de-raced.)
fn test_receive_cancel_deterministic_under_adversarial_delay() {
	caps_set_all()
	mut env := new_env()
	eval_step(mut env, '[?let [= $ch [?channel name="tc16" buffer=0]] [?worker name="tw16" [body [?receive from=$ch]]]]')
	time.sleep(200 * time.millisecond)
	rec := worker_rec(mut env, 'tw16')
	assert !rec.done, '[?receive] on an empty open channel must block (§10.4.3); worker completed with: ${render_canonical(rec.result)}'
	res := eval_step(mut env, '[?let [= $h [?worker-handle name="tw16"]] [?let [= $_ [?cancel worker=$h]] [?wait-for worker=$h]]]')
	rendered := render_canonical(res)
	assert rendered.contains(cancel_chain_outer), 'expected WORKER_CANCELLED chain, got: ${rendered}'
	assert rendered.contains(cancel_chain_cause), 'expected CANCELLED cause, got: ${rendered}'
	assert join_done(rec, 2000), 'worker body never exited its blocked [?receive] after [?cancel]'
	assert rec.cancelled
}

// §10.5.4: [?check-cancel] inside a worker body observes the worker's
// cancel request — a pure spin loop whose only exit is the cancel signal
// (the take-while check-cancel predicate, or the [?for] iteration-boundary
// cancellation point) terminates promptly once [?cancel] lands, and
// [?wait-for] surfaces the WORKER_CANCELLED chain. (program-conc-020,
// de-raced: the loop cannot complete before cancel by construction.
// A recursive [?def] spin is not usable here — def bodies are purity-
// checked and [?check-cancel] is impure, CXER0233.)
fn test_check_cancel_observes_worker_cancel() {
	caps_set_all()
	mut env := new_env()
	eval_step(mut env, '[?worker name="tw20" [body [?for [in $i [$range 1 *]]
      [take-while [?match [?check-cancel] [case [err @code="cx-err:CXER0260"] false] [else true]]]
      [yield $i]]]]')
	// Let the spin loop run hot for a while — pre-fix, [?check-cancel]
	// never observes worker cancellation, so the body can never exit.
	time.sleep(100 * time.millisecond)
	rec := worker_rec(mut env, 'tw20')
	assert !rec.done, 'spin worker must still be looping before [?cancel]; completed with: ${render_canonical(rec.result)}'
	res := eval_step(mut env, '[?let [= $h [?worker-handle name="tw20"]] [?let [= $_ [?cancel worker=$h]] [?wait-for worker=$h]]]')
	rendered := render_canonical(res)
	assert rendered.contains(cancel_chain_outer), 'expected WORKER_CANCELLED chain, got: ${rendered}'
	assert rendered.contains(cancel_chain_cause), 'expected CANCELLED cause, got: ${rendered}'
	assert join_done(rec, 2000), 'worker body never exited its [?check-cancel] spin loop after [?cancel]'
	assert rec.cancelled
}

// §10.5.4 request semantics stay intact: cancelling an ALREADY-COMPLETED
// worker is a no-op — its terminal value is not retroactively replaced.
// (program-conc-012 guard; also proves the fix does not overshoot.)
fn test_cancel_after_done_keeps_value() {
	caps_set_all()
	mut env := new_env()
	eval_step(mut env, '[?worker name="tw12" [body 42]]')
	rec := worker_rec(mut env, 'tw12')
	assert join_done(rec, 2000), 'trivial worker body must complete'
	res := eval_step(mut env, '[?let [= $h [?worker-handle name="tw12"]] [?let [= $_ [?cancel worker=$h]] [?wait-for worker=$h]]]')
	assert render_canonical(res) == '42'
}

// ── #804 leg 7: the frame pool's clear-on-return invariant ──
//
// Leg 7 hands the streamed-input walk's per-item bindings map to the #36
// frame pool instead of allocating one per record. That makes ONE property
// load-bearing on a path where it was not load-bearing before: a map coming
// back OUT of the pool must be EMPTY.
//
// If it were not, the next record's frame would begin life carrying the
// previous record's bindings. And because clone_frame_into then writes the
// base frame's names over the top, such a leak is INVISIBLE for every name
// the two records share — it surfaces only where they differ, which on this
// path means a wrong ANSWER on a well-formed input rather than a crash.
// That is the worst failure shape this engine has, and it is why the
// invariant gets its own test instead of riding on the parity suite.
//
// The invariant lives in return_frame_map (`m.clear()` before pooling).
// Delete that clear and this goes red — verified by doing exactly that,
// not by assuming it.
fn test_frame_pool_returns_cleared_maps() {
	mut pool := &FramePool{}
	mut first := borrow_frame_map(pool)
	first['u'] = cx.Node(cx.ScalarNode{
		value:     cx.ScalarValue(i64(1))
		data_type: .int_type
	})
	first['stale'] = cx.Node(cx.ScalarNode{
		value:     cx.ScalarValue(i64(2))
		data_type: .int_type
	})
	// A probe that never populated the map would assert emptiness vacuously.
	assert first.len == 2, 'the probe must actually populate the borrowed map, else it proves nothing'
	return_frame_map(pool, mut first)
	pooled := pool.free.len

	second := borrow_frame_map(pool)
	assert second.len == 0,
		'#804 leg 7: a pooled frame map came back carrying ${second.len} binding(s) ' +
		'(${second.keys()}) — the next streamed record would inherit them'

	// Dead-seam guard: emptiness also holds trivially if nothing is ever
	// pooled, which would leave leg 7 allocating per record while this test
	// stayed green. Under the escape-detector build that IS the intended
	// behaviour (clear, never reuse), so the claim is made only where reuse
	// is supposed to happen.
	$if !cx_frame_poison ? {
		assert pooled == 1,
			'#804 leg 7: return_frame_map pooled nothing (free.len=${pooled}), so the ' +
			'per-record allocation this leg removes is still being paid'
	}
}

// ── #850: the [?match] bridge/legacy differential ──────────────────────────
//
// #850 took the Z79f bridge off the production `[?match]` hop, on the same
// argument the MODIFY half of that bridge retired on at #803/#805: the legacy
// engine is spec-complete, the bridge's own decline-list already routed every
// hard shape to it, and the bridge served the easy tail ~10x slower.
//
// That change is only safe if the two paths ANSWER THE SAME. The conformance
// corpus going green with the bridge off is weaker evidence than it looks —
// it shows the corpus cannot DISTINGUISH the paths, which is also what you
// would see if the corpus never exercised the difference. So this compares
// them directly, on whole programs, in one process.
//
// WHY NOT REUSE THE EXISTING "bridge vs legacy" HELPER. There is one in
// eval_semantics_umbrella_test.v that compares `try_eval_match_via_bridge`
// against `code.eval_code`. While the bridge was ON the production hop, that
// second arm WENT THROUGH THE BRIDGE for every bridge-eligible program — so
// for exactly the shapes at issue it compared the bridge against itself. It
// was a real differential only for shapes the bridge declines. Recording that
// because it is the same vacuity class as #851 and it survived a long time.
const m850_programs = [
	// [else]-only: the shape the bridge actually served, and the one it was
	// slowest on.
	'[?match [a] [else false]]',
	'[?match 1 [else :none]]',
	// scalar literal cases — the reason Z79g put the bridge on the hop at all
	// (so `[case 200]` types as an int rather than the text "200"). If legacy
	// got scalar typing wrong, THIS is where it shows.
	'[?match 200 [case 200 :match] [else :miss]]',
	'[?match 200 [case 404 :match] [else :miss]]',
	'[?match 0 [case 0 :zero] [else :other]]',
	'[?match -1 [case -1 :neg] [else :other]]',
	"[?match 'x' [case 'x' :hit] [else :miss]]",
	'[?match true [case true :yes] [else :no]]',
	// a scalar case that must NOT match a same-looking string
	"[?match '200' [case 200 :int] [else :notint]]",
	// multiple arms, first-match-wins ordering
	'[?match 2 [case 1 :one] [case 2 :two] [case 3 :three] [else :other]]',
	'[?match 9 [case 1 :one] [case 2 :two] [else :other]]',
	// shapes the bridge DECLINES — included so the corpus covers both sides of
	// the decline boundary, not just the bridge-eligible tail.
	'[?match [a] [case [a] :elem] [else :miss]]',
	'[?match [a] [case [zzz] :elem] [else :miss]]',
]

// m850_empty_programs are the no-`[else]` misses: per §8.2 a multi-arm
// `[?match]` with no matching arm and no `[else]` yields the EMPTY SEQUENCE,
// so these render zero bytes on BOTH paths by design.
//
// They are held apart from the corpus above rather than folded into it,
// because the liveness guard there exists to catch a fixture that produces
// nothing by ACCIDENT, and it cannot tell that from producing nothing by
// SPEC. Folding these in would have meant weakening the guard for every
// program to accommodate two — the #851 rule: if you need to assert both
// paths produce nothing, assert it explicitly where the intent is visible.
// (It fired on exactly this, first run, which is the guard working.)
//
// The agreement claim still holds for them: both paths must construct the
// same empty outcome, and each constructs it separately — the bridge returns
// its own `cx.Element{name:''}`, legacy builds its own.
const m850_empty_programs = [
	'[?match 5 [case 1 :one]]',
	'[?match 9 [case 1 :one] [case 2 :two]]',
]

// m850_eval renders one program through the streaming-free evaluator.
fn m850_eval(prog string) string {
	return eval_code('[x]', prog, 'text') or { 'ERR: ${err.msg()}' }
}

fn test_match_bridge_differential() {
	before := match_bridge_engagements()
	for prog in m850_programs {
		// Shipped routing: bridge OFF.
		set_match_bridge_on(false)
		legacy := m850_eval(prog)
		// Old routing: bridge ON, tried first, declining where it must.
		set_match_bridge_on(true)
		bridged := m850_eval(prog)
		set_match_bridge_on(false)

		// Liveness first — two arms that both fail agree perfectly and prove
		// nothing (#851). A program that errors on both sides is a mis-spelled
		// fixture, not a passing case.
		assert !legacy.starts_with('ERR:'),
			'DEAD FIXTURE — errors on the shipped path, so the comparison is vacuous:\n' +
			'  program : ${prog}\n  error   : ${legacy}'
		assert legacy.len > 0,
			'DEAD FIXTURE — produces no bytes on the shipped path:\n  program : ${prog}'

		assert legacy == bridged,
			'#850 BRIDGE/LEGACY DIVERGENCE — retiring the bridge changed an answer\n' +
			'  program : ${prog}\n  legacy  : ${legacy}\n  bridged : ${bridged}'
	}
	// Dead-seam guard, and the one that matters most here. If no program in the
	// corpus ever engaged the bridge, every comparison above was legacy against
	// legacy — green, and evidence of nothing at all. That is precisely how the
	// pre-existing helper in eval_semantics_umbrella_test.v went quiet.
	engaged := match_bridge_engagements() - before
	assert engaged > 0,
		'#850 VACUOUS DIFFERENTIAL — the bridge never engaged across ${m850_programs.len} ' +
		'programs, so both arms ran the legacy path and the comparison proves nothing'

	// The no-[else] misses: emptiness is the SPEC'd answer, so it is asserted
	// directly here instead of being waved past the liveness guard above.
	for prog in m850_empty_programs {
		set_match_bridge_on(false)
		legacy := m850_eval(prog)
		set_match_bridge_on(true)
		bridged := m850_eval(prog)
		set_match_bridge_on(false)
		assert !legacy.starts_with('ERR:'),
			'no-[else] miss must yield the empty sequence, not an error:\n' +
			'  program : ${prog}\n  got     : ${legacy}'
		assert legacy.len == 0,
			'no-[else] miss must render NOTHING on the shipped path:\n' +
			'  program : ${prog}\n  got     : ${legacy}'
		assert bridged.len == 0,
			'no-[else] miss must render NOTHING via the bridge too:\n' +
			'  program : ${prog}\n  got     : ${bridged}'
	}
}

// test_match_bridge_off_by_default pins the perf fix itself. Without this, a
// future change could quietly restore the bridge to the production hop and the
// differential above would still pass — it asserts AGREEMENT, not which path
// ships. #850 is a performance defect, so which path ships IS the fix.
fn test_match_bridge_off_by_default() {
	assert !match_bridge_enabled(),
		'#850: the Z79f match bridge is back on the production dispatch hop — ' +
		'that is the ~10x per-call regression this issue closed'
	before := match_bridge_engagements()
	// An [else]-only multi-arm match is the shape the bridge used to serve.
	out := m850_eval('[?match [a] [else false]]')
	assert out.len > 0, 'probe produced nothing, so the assertion below is vacuous'
	assert match_bridge_engagements() == before,
		'#850: a multi-arm [?match] still reached the bridge on the default path'
}
